sortChannels(netid, order) {
  const network = _.find(this.networks, {uuid: netid});
  if (!network) { return; }
  network.channels.sort((a, b) => {
    if (a.type === ChanType.LOBBY) { return -1; }
    else if (b.type === ChanType.LOBBY) { return 1; }
    return order.indexOf(a.id) - order.indexOf(b.id);
  });
  this.save();
  this.emit("sync_sort:channels", {network, order});
}

sortNetworks(order) {
  this.networks.sort((a, b) => order.indexOf(a.uuid) - order.indexOf(b.uuid));
  this.save();
  this.emit("sync_sort:networks", {order});
}
